import { useMemo, useState } from 'react';
import { Form, Table } from 'react-bootstrap';
import data from '../../database.json';

const cleanText = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const genderText = (male) => (male ? 'Male' : 'Female');

function Director() {
  const [keyword, setKeyword] = useState('');

  const directors = useMemo(() => {
    const searchText = keyword.trim().toLowerCase();

    return data.directors.filter((director) =>
      cleanText(director.FullName).toLowerCase().includes(searchText)
    );
  }, [keyword]);

  return (
    <section>
      <h2 className="mb-3">Directors List</h2>

      <Form.Control
        className="mb-3"
        type="text"
        placeholder="Search by full name..."
        value={keyword}
        onChange={(event) => setKeyword(event.target.value)}
      />

      <Table striped bordered hover responsive>
        <thead>
          <tr>
            <th>ID</th>
            <th>Full Name</th>
            <th>Gender</th>
            <th>DOB</th>
            <th>Nationality</th>
            <th>Description</th>
          </tr>
        </thead>
        <tbody>
          {directors.map((director) => (
            <tr key={director.id}>
              <td>{director.id}</td>
              <td>{cleanText(director.FullName)}</td>
              <td>{genderText(director.Male)}</td>
              <td>{director.Dob}</td>
              <td>{cleanText(director.Nationality)}</td>
              <td>{cleanText(director.Description)}</td>
            </tr>
          ))}
        </tbody>
      </Table>
    </section>
  );
}

export default Director;
